from fastapi import FastAPI, Security
from fastapi.security import OAuth2PasswordBearer
from fastapi.openapi.utils import get_openapi
import json

app = FastAPI()
oauth2_scheme_1 = OAuth2PasswordBearer(
    tokenUrl="token", 
    scopes={"read": "Read scope"}, 
    scheme_name="oauth2_scheme"
)
oauth2_scheme_2 = OAuth2PasswordBearer(
    tokenUrl="token", 
    scopes={"write": "Write scope"}, 
    scheme_name="oauth2_scheme"
)

@app.get("/read")
def read(token: str = Security(oauth2_scheme_1, scopes=["read"])):
    return {"token": token}

@app.get("/write")
def write(token: str = Security(oauth2_scheme_2, scopes=["write"])):
    return {"token": token}

openapi_schema = get_openapi(app, app.openapi_url)
print(json.dumps(openapi_schema["components"]["securitySchemes"]["oauth2_scheme"]["flows"]["password"]["scopes"], indent=2))
